from pathlib import Path
import subprocess,shlex,json
root=Path(__file__).resolve().parents[2]
source=(root/'_codex/scripts/deploy_error_triage.py').read_text().split("if __name__=='__main__':")[0].replace('ROOT=Path(__file__).resolve().parents[2]',"ROOT=Path('/var/www/business.roadrunners.run')")
body='report={};q=queryExecute("SELECT l.id_log,l.log_item,l.log_item_id,l.site FROM tb_log l WHERE l.log_item IN (\'erro\',\'404\') AND l.log_timestamp>=timestamp \'2026-09-19 21:40:47\' AND l.id_log<=45375598 AND NOT EXISTS(SELECT 1 FROM tb_error_occurrence o WHERE o.id_log=l.id_log) ORDER BY l.id_log LIMIT 201",{},{datasource="runner_dba",timeout=12});n=new portal.erros.includes.ErrorNormalizer();report.checked=0;report.failures=[];for(row in q){try{r=n.normalize(row);report.checked++;if(len(r.path)>320||len(r.technicalMessage)>500||len(row.site)>32)arrayAppend(report.failures,{id=row.id_log,path_length=len(r.path),message_length=len(r.technicalMessage),site_length=len(row.site)});}catch(any e){arrayAppend(report.failures,{id=row.id_log,type=e.type,message=left(e.message,180),line=e.tagContext[1].line});break;}}'
